[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #0A0A0A;
      --white: #FFFFFF;
      --gray: #808080;
      --light-gray: #1A1A1A;
      --border: #2A2A2A;
      --accent: #3B82F6;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--black);
      color: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(10, 10, 10, 0.9);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
    }

    .nav-inner {
      max-width: 1400px;
      margin: 0 auto;
      padding: 0 40px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .nav-logo {
      font-size: 24px;
      font-weight: 800;
      letter-spacing: -1px;
    }

    .nav-links {
      display: flex;
      gap: 40px;
      list-style: none;
    }

    .nav-links a {
      color: var(--white);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      opacity: 0.8;
      transition: opacity 0.2s;
    }

    .nav-links a:hover { opacity: 1; }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 24px;
    }

    .lang-selector {
      position: relative;
    }

    .lang-btn {
      background: none;
      border: 1px solid var(--border);
      color: var(--white);
      padding: 8px 16px;
      font-size: 13px;
      font-weight: 500;
      cursor: pointer;
      border-radius: 6px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .lang-btn:hover { border-color: var(--gray); }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 0;
      min-width: 160px;
      display: none;
      box-shadow: 0 20px 40px rgba(0,0,0,0.5);
    }

    .lang-dropdown.active { display: block; }

    .lang-dropdown button {
      width: 100%;
      background: none;
      border: none;
      color: var(--white);
      padding: 10px 20px;
      text-align: left;
      font-size: 13px;
      cursor: pointer;
    }

    .lang-dropdown button:hover { background: var(--border); }

    .nav-cta {
      background: var(--white);
      color: var(--black);
      border: none;
      padding: 10px 20px;
      font-size: 13px;
      font-weight: 600;
      border-radius: 6px;
      cursor: pointer;
    }

    .nav-cta:hover { opacity: 0.9; }

    /* Mobile Nav */
    .nav-toggle {
      display: none;
      background: none;
      border: none;
      color: var(--white);
      font-size: 24px;
      cursor: pointer;
    }

    @media (max-width: 900px) {
      .nav-links { display: none; }
      .nav-toggle { display: block; }
      .nav-inner { padding: 0 20px; }
    }

    /* Hero Carousel */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      padding: 120px 40px 80px;
    }

    .hero-inner {
      max-width: 1400px;
      margin: 0 auto;
      width: 100%;
    }

    .hero-carousel {
      position: relative;
    }

    .hero-slides {
      display: flex;
      transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .hero-slide {
      min-width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .hero-content {
      max-width: 600px;
    }

    .hero-tag {
      display: inline-block;
      background: var(--light-gray);
      border: 1px solid var(--border);
      padding: 6px 12px;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 24px;
      border-radius: 4px;
    }

    .hero-title {
      font-size: clamp(40px, 5vw, 72px);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -3px;
      margin-bottom: 24px;
    }

    .hero-desc {
      font-size: 18px;
      color: var(--gray);
      margin-bottom: 40px;
      line-height: 1.7;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      color: var(--black);
      padding: 14px 28px;
      font-size: 14px;
      font-weight: 600;
      text-decoration: none;
      border-radius: 8px;
      border: none;
      cursor: pointer;
      transition: transform 0.2s;
    }

    .hero-cta:hover { transform: translateY(-2px); }

    .hero-image {
      position: relative;
      aspect-ratio: 4/3;
      border-radius: 16px;
      overflow: hidden;
      background: var(--light-gray);
    }

    .hero-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-dots {
      display: flex;
      gap: 8px;
      margin-top: 48px;
    }

    .hero-dot {
      width: 40px;
      height: 4px;
      background: var(--border);
      border-radius: 2px;
      cursor: pointer;
      transition: background 0.3s;
    }

    .hero-dot.active { background: var(--white); }

    @media (max-width: 900px) {
      .hero { padding: 100px 20px 60px; }
      .hero-slide { grid-template-columns: 1fr; gap: 40px; }
      .hero-image { order: -1; }
    }

    /* Team Section */
    .team {
      padding: 120px 40px;
      background: var(--black);
    }

    .section-header {
      text-align: center;
      max-width: 700px;
      margin: 0 auto 60px;
    }

    .section-title {
      font-size: clamp(32px, 4vw, 56px);
      font-weight: 800;
      letter-spacing: -2px;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: 18px;
      color: var(--gray);
    }

    .region-tabs {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-bottom: 60px;
      flex-wrap: wrap;
    }

    .region-tab {
      background: none;
      border: 1px solid var(--border);
      color: var(--gray);
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      border-radius: 8px;
      transition: all 0.3s;
    }

    .region-tab:hover { border-color: var(--gray); color: var(--white); }

    .region-tab.active {
      background: var(--white);
      color: var(--black);
      border-color: var(--white);
    }

    .team-carousel-wrap {
      position: relative;
      max-width: 1200px;
      margin: 0 auto;
    }

    .team-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      padding: 20px 0;
      -webkit-overflow-scrolling: touch;
    }

    .team-carousel::-webkit-scrollbar { display: none; }

    .team-card {
      min-width: 340px;
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 16px;
      overflow: hidden;
      scroll-snap-align: start;
      flex-shrink: 0;
    }

    .team-photo {
      aspect-ratio: 3/4;
      background: var(--border);
      position: relative;
    }

    .team-photo img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: grayscale(20%);
    }

    .team-info {
      padding: 24px;
    }

    .team-quote {
      font-size: 15px;
      font-style: italic;
      color: var(--gray);
      margin-bottom: 16px;
      line-height: 1.6;
    }

    .team-name {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .team-title {
      font-size: 13px;
      color: var(--gray);
      margin-bottom: 12px;
    }

    .team-office {
      font-size: 13px;
      color: var(--accent);
      text-decoration: none;
    }

    @media (max-width: 600px) {
      .team { padding: 80px 20px; }
      .team-card { min-width: 280px; }
      .region-tab { padding: 10px 16px; font-size: 13px; }
    }

    /* Work Section */
    .work {
      padding: 120px 40px;
      background: #0F0F0F;
    }

    .work-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .work-card {
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.3s;
    }

    .work-card:hover { transform: translateY(-4px); }

    .work-img {
      aspect-ratio: 16/10;
      background: var(--border);
      overflow: hidden;
    }

    .work-img img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.5s;
    }

    .work-card:hover .work-img img { transform: scale(1.05); }

    .work-body { padding: 24px; }

    .work-client {
      font-size: 12px;
      color: var(--gray);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 8px;
    }

    .work-title {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 12px;
      line-height: 1.4;
    }

    .work-quote {
      font-size: 14px;
      color: var(--gray);
      line-height: 1.6;
    }

    .work-author {
      display: block;
      margin-top: 8px;
      font-size: 12px;
      color: var(--accent);
    }

    .work-scroll {
      display: none;
      gap: 20px;
      overflow-x: auto;
      padding: 20px 0;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
    }

    .work-scroll .work-card {
      min-width: 340px;
      scroll-snap-align: start;
    }

    @media (max-width: 900px) {
      .work-grid { display: none; }
      .work-scroll { display: flex; }
    }

    @media (max-width: 600px) {
      .work { padding: 80px 20px; }
      .work-scroll .work-card { min-width: 280px; }
    }

    /* CTA Banner */
    .cta-banner {
      padding: 100px 40px;
      background: linear-gradient(135deg, #1a1a2e 0%, var(--black) 100%);
      text-align: center;
    }

    .cta-inner { max-width: 800px; margin: 0 auto; }

    .cta-title {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800;
      letter-spacing: -2px;
      margin-bottom: 20px;
    }

    .cta-body {
      font-size: 18px;
      color: var(--gray);
      margin-bottom: 40px;
    }

    .cta-btn {
      display: inline-block;
      background: var(--white);
      color: var(--black);
      padding: 16px 32px;
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      border-radius: 8px;
      border: none;
      cursor: pointer;
      transition: transform 0.2s;
    }

    .cta-btn:hover { transform: translateY(-2px); }

    /* How We Work */
    .how-we-work {
      padding: 120px 40px;
      background: var(--black);
    }

    .how-inner {
      max-width: 900px;
      margin: 0 auto;
      text-align: center;
    }

    .how-title {
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 800;
      letter-spacing: -1px;
      margin-bottom: 24px;
    }

    .how-body {
      font-size: 18px;
      color: var(--gray);
      line-height: 1.8;
      margin-bottom: 40px;
    }

    .how-btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: none;
      border: 1px solid var(--border);
      color: var(--white);
      padding: 14px 28px;
      font-size: 14px;
      font-weight: 600;
      text-decoration: none;
      border-radius: 8px;
      cursor: pointer;
      transition: border-color 0.2s;
    }

    .how-btn:hover { border-color: var(--gray); }

    /* Insights */
    .insights {
      padding: 120px 40px;
      background: #0F0F0F;
    }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .insight-card {
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      transition: transform 0.3s;
    }

    .insight-card:hover { transform: translateY(-4px); }

    .insight-img {
      aspect-ratio: 1;
      background: var(--border);
      position: relative;
    }

    .insight-type {
      position: absolute;
      bottom: 12px;
      left: 12px;
      background: var(--black);
      padding: 4px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      border-radius: 4px;
    }

    .insight-body { padding: 20px; }

    .insight-title {
      font-size: 15px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 12px;
    }

    .insight-cta {
      font-size: 13px;
      color: var(--accent);
      text-decoration: none;
      font-weight: 500;
    }

    @media (max-width: 900px) {
      .insights-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 600px) {
      .insights { padding: 80px 20px; }
      .insights-grid { grid-template-columns: 1fr; }
      .insight-card { display: flex; }
      .insight-img { width: 120px; aspect-ratio: 1; }
    }

    /* Principles */
    .principles {
      padding: 120px 40px;
      background: var(--black);
    }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 40px;
      max-width: 1000px;
      margin: 0 auto;
    }

    .principle-card {
      padding: 40px;
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 16px;
    }

    .principle-num {
      font-size: 14px;
      color: var(--accent);
      font-weight: 600;
      margin-bottom: 16px;
    }

    .principle-title {
      font-size: 24px;
      font-weight: 700;
      margin-bottom: 16px;
    }

    .principle-body {
      font-size: 15px;
      color: var(--gray);
      line-height: 1.7;
    }

    @media (max-width: 700px) {
      .principles { padding: 80px 20px; }
      .principles-grid { grid-template-columns: 1fr; gap: 24px; }
      .principle-card { padding: 28px; }
    }

    /* Footer */
    .footer {
      background: #0F0F0F;
      padding: 80px 40px 40px;
    }

    .footer-ctas {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 40px;
      max-width: 1000px;
      margin: 0 auto 80px;
    }

    .footer-cta {
      text-align: center;
      padding: 40px;
      background: var(--light-gray);
      border: 1px solid var(--border);
      border-radius: 16px;
    }

    .footer-cta-title {
      font-size: 24px;
      font-weight: 700;
      margin-bottom: 12px;
    }

    .footer-cta-body {
      font-size: 14px;
      color: var(--gray);
      margin-bottom: 24px;
    }

    .footer-cta-btn {
      display: inline-block;
      background: var(--white);
      color: var(--black);
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 600;
      text-decoration: none;
      border-radius: 6px;
      border: none;
      cursor: pointer;
    }

    .footer-links {
      display: flex;
      justify-content: center;
      gap: 40px;
      margin-bottom: 40px;
      flex-wrap: wrap;
    }

    .footer-links a {
      color: var(--gray);
      text-decoration: none;
      font-size: 14px;
      transition: color 0.2s;
    }

    .footer-links a:hover { color: var(--white); }

    .footer-legal {
      text-align: center;
      font-size: 12px;
      color: var(--gray);
      padding-top: 40px;
      border-top: 1px solid var(--border);
    }

    .footer-legal a {
      color: var(--gray);
      text-decoration: none;
      margin: 0 12px;
    }

    .footer-legal a:hover { color: var(--white); }

    @media (max-width: 700px) {
      .footer-ctas { grid-template-columns: 1fr; }
      .footer { padding: 60px 20px 30px; }
    }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--light-gray);
      border-top: 1px solid var(--border);
      padding: 20px 40px;
      display: none;
      z-index: 999;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .cookie-banner.active { display: flex; }

    .cookie-text {
      font-size: 14px;
      color: var(--gray);
      max-width: 600px;
    }

    .cookie-text a { color: var(--white); }

    .cookie-btns {
      display: flex;
      gap: 12px;
      flex-shrink: 0;
    }

    .cookie-btn {
      padding: 10px 20px;
      font-size: 13px;
      font-weight: 600;
      border-radius: 6px;
      cursor: pointer;
      border: none;
    }

    .cookie-accept {
      background: var(--white);
      color: var(--black);
    }

    .cookie-settings {
      background: none;
      border: 1px solid var(--border);
      color: var(--white);
    }

    .cookie-decline {
      background: none;
      border: 1px solid var(--border);
      color: var(--gray);
    }

    @media (max-width: 700px) {
      .cookie-banner { flex-direction: column; padding: 20px; }
      .cookie-btns { width: 100%; }
      .cookie-btn { flex: 1; }
    }
  </style>
</head>
